import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Snaplink — enlaces cortos, analítica real","description":"Acortador de URLs autoalojado con analítica por clic: Next.js 14 App Router, TypeScript, Prisma, SQLite y Tailwind CSS.","frontmatter":{"title":"Snaplink — enlaces cortos, analítica real","description":"Acortador de URLs autoalojado con analítica por clic: Next.js 14 App Router, TypeScript, Prisma, SQLite y Tailwind CSS."},"headers":[],"relativePath":"es/projects/snaplink/index.md","filePath":"es/projects/snaplink/index.md"}`),a={name:`es/projects/snaplink/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="snaplink-—-enlaces-cortos-analitica-real" tabindex="-1">Snaplink — enlaces cortos, analítica real <a class="header-anchor" href="#snaplink-—-enlaces-cortos-analitica-real" aria-label="Permalink to “Snaplink — enlaces cortos, analítica real”">​</a></h1><p><strong><a href="https://github.com/Godde3s/snaplink" target="_blank" rel="noreferrer">Snaplink</a></strong> es una alternativa completa y autoalojada a los acortadores comerciales — la misma base de código sirve la API, el borde de redirección y el panel de analítica. Es lo bastante pequeño para entenderlo de una sentada y lo bastante real para servir a una comunidad.</p><h2 id="que-hace" tabindex="-1">Qué hace <a class="header-anchor" href="#que-hace" aria-label="Permalink to “Qué hace”">​</a></h2><ul><li><strong>Acorta cualquier URL</strong> — slugs de 7 caracteres de un alfabeto sin ambigüedades (sin <code>0/O/1/l</code>), con reintento automático ante colisiones.</li><li><strong>Analítica de clics</strong> — totales por enlace, referrers principales e histograma de 14 días vía <code>groupBy</code> de Prisma.</li><li><strong>Redirección rápida</strong> — <code>/r/:slug</code> registra la visita <em>como pueda</em> y redirige al instante; la analítica nunca rompe un redirect.</li><li><strong>SQLite por defecto</strong> — cero configuración; pasar a Postgres es cambiar una línea.</li></ul><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:3000/api/links</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\\\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;content-type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\\\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;url&quot;:&quot;https://github.com/Godde3s&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># {&quot;link&quot;:{&quot;slug&quot;:&quot;k7mp2ax&quot;, ...}}</span></span></code></pre></div><h2 id="notas-de-ingenieria" tabindex="-1">Notas de ingeniería <a class="header-anchor" href="#notas-de-ingenieria" aria-label="Permalink to “Notas de ingeniería”">​</a></h2><p>El handler de redirección es deliberadamente aburrido: buscar el slug, aislar la analítica en su propio try/catch y redirigir. La validación rechaza todo lo que no sea una URL absoluta <code>http(s)</code> con hostname real — <code>javascript:</code> muere en la puerta. <strong>Tests unitarios</strong> cubren validación, generación de slugs y bucketing de referrers; CI ejecuta <code>vitest</code> + <code>tsc --noEmit</code>. Licencia MIT.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};